SELECT test.prepare_dispute_command('C47MULTI');
SELECT set_config('test.c47.doc',test.command_doc('C47MULTI-BBNT')::text,true),set_config('test.c47.lines',(SELECT jsonb_agg(jsonb_build_object('lot_id',test.id('C47MULTI:lot'),'kind','rejected','qty',1000000,'payable_qty',0,'unit_price_vnd',0,'value_vnd',0,'reason_code',(SELECT r.reason_code FROM core.product_reject_reasons r JOIN core.lots l ON l.product_id=r.product_id AND l.profile_version=r.profile_version WHERE l.id=test.id('C47MULTI:lot') ORDER BY r.reason_code LIMIT 1))) FROM generate_series(1,2))::text,true);
SELECT test.as_login('db_test_receiver',$$SELECT set_config('test.c47.acceptance',cmd.submit_acceptance(current_setting('test.c47.delivery')::uuid,2000000,current_setting('test.c47.doc')::jsonb,current_setting('test.c47.lines')::jsonb)::text,true)$$);
SELECT set_config('test.c47.docid',(SELECT document_id::text FROM core.acceptance_versions WHERE id=current_setting('test.c47.acceptance')::uuid),true),set_config('test.c47.line1',(SELECT id::text FROM core.acceptance_lines WHERE acceptance_id=current_setting('test.c47.acceptance')::uuid AND line_no=1),true),set_config('test.c47.line2',(SELECT id::text FROM core.acceptance_lines WHERE acceptance_id=current_setting('test.c47.acceptance')::uuid AND line_no=2),true);
SELECT test.sign_command_record('db_test_receiver',test.person('Võ Hoàng Phúc'),'buyer');
SELECT test.as_login('db_test_receiver',$$SELECT cmd.send_acceptance(current_setting('test.c47.acceptance')::uuid)$$);
SELECT test.sign_command_record('db_test_seller',test.person('Nguyễn Thị Năm'),'seller');
SELECT test.as_login('db_test_seller',$$SELECT set_config('test.c47.dispute1',cmd.open_dispute(current_setting('test.c47.line1')::uuid,1000000,'Phản đối dòng 1')::text,true)$$);
SELECT test.as_login('db_test_seller',$$SELECT set_config('test.c47.dispute2',cmd.open_dispute(current_setting('test.c47.line2')::uuid,1000000,'Phản đối dòng 2')::text,true)$$);
SELECT set_config('test.c47.provider',test.org('DT-KD')::text,true);
SELECT test.as_login('db_test_buyer',$$SELECT set_config('test.c47.inspection1',cmd.request_inspection(current_setting('test.c47.dispute1')::uuid,current_setting('test.c47.provider')::uuid,NULL,0,NULL)::text,true)$$);
SELECT test.as_login('db_test_buyer',$$SELECT set_config('test.c47.inspection2',cmd.request_inspection(current_setting('test.c47.dispute2')::uuid,current_setting('test.c47.provider')::uuid,NULL,0,NULL)::text,true)$$);
SELECT set_config('test.c47.report',test.command_doc('C47MULTI-REPORT1')::text,true);
SELECT test.as_login('db_test_inspector',$$SELECT cmd.record_inspection_result(current_setting('test.c47.inspection1')::uuid,'C47MULTI-EVENT1','inconclusive',current_setting('test.c47.report')::jsonb,'{}',NULL)$$);
SELECT set_config('test.c47.deadline',(SELECT id::text FROM core.deadlines WHERE entity_id=current_setting('test.c47.dispute1')::uuid AND kind='dispute_agreement' AND status='open'),true);
SELECT test.as_login('db_test_system',$$SELECT test.expect_error('C47 không chuyển cơ chế khác trước 14 ngày','SELECT cmd.expire_deadline_result(current_setting(''test.c47.deadline'')::uuid)','ck_deadline_not_due')$$);
INSERT INTO cmd.test_clock(at) VALUES(now()+interval '15 days');
SELECT test.as_login('db_test_system',$$SELECT cmd.expire_deadline_result(current_setting('test.c47.deadline')::uuid)$$);
DELETE FROM cmd.test_clock;
SELECT test.check('C47 không kết luận 14 ngày giữ nguyên tiền và tạo việc risk',EXISTS(SELECT 1 FROM core.disputes WHERE id=current_setting('test.c47.dispute1')::uuid AND status='external_resolution') AND EXISTS(SELECT 1 FROM ops.tasks WHERE entity_id=current_setting('test.c47.dispute1')::uuid AND required_role='risk') AND NOT EXISTS(SELECT 1 FROM core.bank_instructions WHERE order_id=test.id('C47MULTI')));
SELECT set_config('test.c47.evidence',test.command_doc('C47MULTI-DECISION-EVIDENCE')::text,true);
SELECT test.as_login('db_test_seller',$$SELECT set_config('test.c47.evidenceid',cmd.attach_evidence(current_setting('test.c47.order')::uuid,current_setting('test.c47.evidence')::jsonb)::text,true)$$);
SELECT test.as_login('db_test_verify',$$SELECT set_config('test.c47.proposal',cmd.propose_decision('dispute_resolution','dispute',current_setting('test.c47.dispute1')::uuid,'Kết luận sau cơ chế khác',current_setting('test.c47.evidenceid')::uuid,'{"result":"failed"}')::text,true)$$);
SELECT test.as_login('db_test_approve',$$SELECT set_config('test.c47.decision',cmd.approve_decision(current_setting('test.c47.proposal')::uuid)::text,true)$$);
SELECT set_config('test.c47.resolutiondoc',test.command_doc('C47MULTI-RESOLUTION1')::text,true);
SELECT test.as_login('db_test_verify',$$SELECT test.expect_error('C47 người lập không thay người duyệt phân xử','SELECT cmd.resolve_dispute(current_setting(''test.c47.dispute1'')::uuid,current_setting(''test.c47.decision'')::uuid,current_setting(''test.c47.resolutiondoc'')::jsonb)','KHONG_CO_QUYEN')$$);
SELECT test.as_login('db_test_approve',$$SELECT cmd.resolve_dispute(current_setting('test.c47.dispute1')::uuid,current_setting('test.c47.decision')::uuid,current_setting('test.c47.resolutiondoc')::jsonb)$$);
SELECT test.check('C47 kết luận dòng 1 vẫn giữ dòng 2 tranh chấp',(SELECT count(*)=1 FROM core.acceptance_lines WHERE acceptance_id=(SELECT id FROM core.acceptance_versions WHERE delivery_id=current_setting('test.c47.delivery')::uuid ORDER BY version_no DESC LIMIT 1) AND status='disputed'));
SELECT test.as_login('db_test_system',$$SELECT test.expect_error('C47 không đóng đợt còn dòng tranh chấp','SELECT cmd.close_resolved_delivery(current_setting(''test.c47.delivery'')::uuid)','ck_command_acceptance')$$);
SELECT set_config('test.c47.report',test.command_doc('C47MULTI-REPORT2')::text,true),set_config('test.c47.resolutiondoc',test.command_doc('C47MULTI-RESOLUTION2')::text,true);
SELECT test.as_login('db_test_inspector',$$SELECT cmd.record_inspection_result(current_setting('test.c47.inspection2')::uuid,'C47MULTI-EVENT2','passed',current_setting('test.c47.report')::jsonb,'{}',current_setting('test.c47.resolutiondoc')::jsonb)$$);
SELECT test.as_login('db_test_system',$$SELECT cmd.close_resolved_delivery(current_setting('test.c47.delivery')::uuid)$$);
SELECT test.check('C47 hai kết luận nối phiên bản, bảo toàn 1000kg đạt + 1000kg trả',(SELECT count(*)=3 FROM core.acceptance_versions WHERE delivery_id=current_setting('test.c47.delivery')::uuid) AND (SELECT count(*)=2 FROM core.dispute_resolutions r JOIN core.disputes d ON d.id=r.dispute_id WHERE d.order_id=test.id('C47MULTI')) AND EXISTS(SELECT 1 FROM ledger.qty_balances WHERE order_key=test.id('C47MULTI') AND bucket='delivered' AND qty=1000000) AND EXISTS(SELECT 1 FROM ledger.qty_balances WHERE order_key=test.id('C47MULTI') AND bucket='returned_pending' AND qty=1000000));
SELECT test.as_login('db_test_system',$$SELECT cmd.create_settlement(current_setting('test.c47.order')::uuid,true,'C47MULTI-FINAL')$$);
SELECT test.check('C47 quyết toán chỉ lấy bản cuối 23 triệu',EXISTS(SELECT 1 FROM core.settlements WHERE order_id=test.id('C47MULTI') AND is_final AND v_vnd=23000000));
SET CONSTRAINTS ALL IMMEDIATE;
